package com.cpf.batch.agent; import java.util.Set; public final class ApprovedCommandCatalog { private static final Set<String> ALLOWED=Set.of("INSTALL_ARTIFACT","START","STOP","RESTART","STATUS","DRAIN","RESUME","UPGRADE","ROLLBACK","COLLECT_LOGS","QUARANTINE");public void requireAllowed(String c){if(!ALLOWED.contains(c))throw new SecurityException("Unapproved agent command");} }